package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Rect;import android.view.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.concurrent.*;

/** Disposable emulator acceptance checks using a local MP4, with screenshots. */
public class NativePlayerTest extends Instrumentation {
 Activity activity;int passed,failed;StringBuilder report=new StringBuilder();
 interface Task{void run()throws Exception;}interface Condition{boolean test()throws Exception;}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 Object host()throws Exception{Field f=activity.getClass().getDeclaredField("host");f.setAccessible(true);return f.get(activity);}
 Object field(String name)throws Exception{Object h=host();Field f=h.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(h);}
 boolean onMain(Condition c)throws Exception{boolean[] out={false};Throwable[] error={null};runOnMainSync(()->{try{out[0]=c.test();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);return out[0];}
 void dismissSystemOverlays(){try{android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return;for(String label:new String[]{"Got it","Wait"})for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label)){for(int i=0;i<3&&node!=null;i++,node=node.getParent())if(node.isClickable()){node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);break;}}}catch(Exception ignored){}}
 void waitFor(Condition c)throws Exception{long until=SystemClock.uptimeMillis()+60000;while(SystemClock.uptimeMillis()<until){dismissSystemOverlays();if(onMain(c))return;SystemClock.sleep(150);}throw new AssertionError("Condition timeout");}
 Object playerCall(String method)throws Exception{return Class.forName("androidx.media3.common.Player",true,activity.getClassLoader()).getMethod(method).invoke(field("player"));}
 boolean playing()throws Exception{return (boolean)playerCall("isPlaying");}
 void tap(String name)throws Exception{dismissSystemOverlays();waitFor(()->activity.hasWindowFocus());show();tapView((View)field(name));}
 View findLabel(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=findLabel(g.getChildAt(i),label);if(found!=null)return found;}}return null;}
 void tapLabel(String label)throws Exception{dismissSystemOverlays();waitFor(()->activity.hasWindowFocus());show();View[] target={null};runOnMainSync(()->{try{target[0]=findLabel((View)field("root"),label);}catch(Exception e){throw new RuntimeException(e);}});require(target[0]!=null,"Missing button "+label);tapView(target[0]);}
 void tapView(View v)throws Exception{int[] xy=new int[2];runOnMainSync(()->v.getLocationOnScreen(xy));float x=xy[0]+v.getWidth()/2f,y=xy[1]+v.getHeight()/2f;long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0));sendPointerSync(MotionEvent.obtain(t,t+60,MotionEvent.ACTION_UP,x,y,0));SystemClock.sleep(150);}

 void show()throws Exception{runOnMainSync(()->{try{Object h=host();Method m=h.getClass().getDeclaredMethod("showControls");m.setAccessible(true);m.invoke(h);}catch(Exception e){throw new RuntimeException(e);}});}
 void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 void check(String name,Task task){try{task.run();passed++;report.append("PASS ").append(name).append('\n');}catch(Throwable e){failed++;report.append("FAIL ").append(name).append(" ").append(e.toString()).append('\n');try{onMain(()->{report.append("STATE ").append(((TextView)field("status")).getText()).append(" focus=").append(activity.hasWindowFocus()).append(" state=").append(playerCall("getPlaybackState")).append('\n');return true;});}catch(Exception ignored){}}Bundle b=new Bundle();b.putString("stream",report.toString());sendStatus(0,b);}
 void inspect(View v,Rect screen,float density)throws Exception{if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof ImageButton){Rect r=new Rect();if(!v.getGlobalVisibleRect(r))return;require(r.left>=screen.left&&r.right<=screen.right&&r.top>=screen.top&&r.bottom<=screen.bottom,"Button outside screen: "+v.getContentDescription());require(v.getWidth()>=48*density-1&&v.getHeight()>=48*density-1,"Small touch area: "+v.getContentDescription());ImageButton b=(ImageButton)v;android.graphics.RectF icon=new android.graphics.RectF(b.getDrawable().getBounds());b.getImageMatrix().mapRect(icon);require(Math.abs(icon.centerX()+b.getPaddingLeft()-b.getWidth()/2f)<=1.5f&&Math.abs(icon.centerY()+b.getPaddingTop()-b.getHeight()/2f)<=1.5f,"Icon not centered: "+b.getContentDescription());require(b.getPaddingLeft()==b.getPaddingRight()&&b.getPaddingTop()==b.getPaddingBottom(),"Asymmetric icon padding");report.append("BUTTON ").append(b.getContentDescription()).append(" ").append(r).append('\n');}if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)inspect(g.getChildAt(i),screen,density);}}
 void capture(String name)throws Exception{show();SystemClock.sleep(250);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();java.io.File dir=new java.io.File(getTargetContext().getExternalFilesDir(null),"player-tests");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 @Override public void onStart(){try{
  Intent intent=new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.NativePlaybackActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);intent.putExtra("payload",new JSONObject().put("url","http://10.0.2.2:18888/demo.mp4").put("name","TiviLoom test channel").toString());activity=startActivitySync(intent);
  check("native first frame and playback",()->waitFor(()->{Object size=playerCall("getVideoSize");return playing()&&size.getClass().getField("width").getInt(size)>0;}));
  runOnMainSync(()->{try{Class.forName("androidx.media3.common.Player",true,activity.getClassLoader()).getMethod("setRepeatMode",int.class).invoke(field("player"),1);}catch(Exception e){throw new RuntimeException(e);}});
  check("landscape controls bounded with centered 48dp touch targets",()->{show();require(onMain(()->{View root=(View)field("root");require(root.getWidth()>root.getHeight(),"Not landscape");inspect(root,new Rect(0,0,root.getWidth(),root.getHeight()),activity.getResources().getDisplayMetrics().density);return true;}),"Layout check");capture("fullscreen-controls");});
  check("pause and resume",()->{show();tap("playButton");waitFor(()->!playing());tap("playButton");waitFor(()->playing());});
  check("screen lock and unlock",()->{show();tap("lockButton");waitFor(()->((View)field("controls")).getVisibility()==View.GONE);tap("lockButton");waitFor(()->((View)field("controls")).getVisibility()==View.VISIBLE);});
  check("seek controls enabled for VOD",()->{show();require(onMain(()->((View)field("seek")).getVisibility()==View.VISIBLE&&((View)field("forward")).isEnabled()),"Seek disabled");tap("forward");});
  check("display mode button changes video sizing",()->{int[] before={0};onMain(()->{Object view=field("playerView");before[0]=(int)view.getClass().getMethod("getResizeMode").invoke(view);return true;});tapLabel("Görüntü ölçüsü");waitFor(()->{Object view=field("playerView");return (int)view.getClass().getMethod("getResizeMode").invoke(view)!=before[0];});});
  check("audio menu opens and closes",()->{tapLabel("Səs dilini seç");waitFor(()->(boolean)field("dialogOpen")&&!activity.hasWindowFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->!(boolean)field("dialogOpen")&&activity.hasWindowFocus());});
  check("subtitle menu opens and closes",()->{tapLabel("Altyazı seç");waitFor(()->(boolean)field("dialogOpen")&&!activity.hasWindowFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->!(boolean)field("dialogOpen")&&activity.hasWindowFocus());});
  check("preview/fullscreen keeps decoder and timeline",()->{Object original=field("player");long[] position={0};onMain(()->{position[0]=(long)playerCall("getCurrentPosition");return true;});runOnMainSync(()->{try{Object h=host();h.getClass().getMethod("setFullscreen",boolean.class).invoke(h,false);h.getClass().getMethod("setFullscreen",boolean.class).invoke(h,true);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->playing()&&(long)playerCall("getCurrentPosition")>position[0]);require(field("player")==original,"Decoder replaced on fullscreen transition");});
  for(String label:new String[]{"Axtar","Kanal siyahısı","Tarixçə"})check(label+" panel preserves playback",()->{Object original=field("player");tapLabel(label);waitFor(()->(boolean)field("dialogOpen")&&!activity.hasWindowFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->!(boolean)field("dialogOpen")&&activity.hasWindowFocus());require(field("player")==original,"Panel replaced player");});
  check("back exits native player",()->{dismissSystemOverlays();waitFor(()->activity.hasWindowFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->activity.isFinishing()||activity.isDestroyed());});
 }catch(Throwable e){failed++;report.append("FATAL ").append(e.toString());}Bundle result=new Bundle();result.putString("stream",report+"\nPASSED="+passed+" FAILED="+failed+"\n");finish(failed==0?-1:0,result);}
}
